import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises'
import { basename, join, resolve } from 'node:path'
import { compile } from 'json-schema-to-typescript'
import { log } from './logger.mjs'

const INPUT_DIR = resolve('src/schemas')
const OUTPUT_DIR = resolve('src/models/generated')
const SCHEMA_EXTENSION = '.schema.json'

const BANNER_COMMENT = `/* biome-ignore lint: Generated file - do not edit directly */
/* Generated by json-schema-to-typescript - do not edit directly */`

async function generateType(filename) {
  const schemaPath = join(INPUT_DIR, filename)
  const typeName = basename(filename, SCHEMA_EXTENSION)
  const outputPath = join(OUTPUT_DIR, `${typeName}.d.ts`)

  const raw = await readFile(schemaPath, 'utf8')
  const schema = JSON.parse(raw)

  const types = await compile(schema, schema.title ?? typeName, {
    bannerComment: BANNER_COMMENT,
    format: true
  })

  await writeFile(outputPath, `${types.trim()}\n`, 'utf8')
  log.success(`File: ${filename} -> ${typeName}.d.ts`)
}

async function main() {
  const startTime = performance.now()

  await mkdir(OUTPUT_DIR, { recursive: true })

  const entries = await readdir(INPUT_DIR).catch((err) => {
    throw new Error(`Failed to read input directory "${INPUT_DIR}": ${err.message}`)
  })

  const schemaFiles = entries.filter((file) => file.endsWith(SCHEMA_EXTENSION))

  if (schemaFiles.length === 0) {
    log.warn(`No "${SCHEMA_EXTENSION}" files found in ${INPUT_DIR}`)
    return
  }

  log.info(`Compiling ${schemaFiles.length} schema(s) concurrently...`)

  const results = await Promise.allSettled(schemaFiles.map(generateType))
  const failed = results.filter((r) => r.status === 'rejected')

  const duration = ((performance.now() - startTime) / 1000).toFixed(2)

  if (failed.length > 0) {
    for (const error of failed) {
      log.error(error.reason?.message ?? error.reason)
    }
    throw new Error(
      `Failed generating ${failed.length} of ${schemaFiles.length} type definition(s).`
    )
  }

  log.info(`All types generated successfully in ${duration}s.`)
}

try {
  await main()
} catch (error) {
  log.error(error.message)
  process.exitCode = 1
}
